/**
 * @suppress
 */
public object FfiConverterString: FfiConverter<String, RustBuffer.ByValue> {
    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    override fun lift(value: RustBuffer.ByValue): String {
        try {
            val byteArr = ByteArray(value.len.toInt())
            value.asByteBuffer()!!.get(byteArr)
            return byteArr.toString(Charsets.UTF_8)
        } finally {
            RustBuffer.free(value)
        }
    }

    override fun read(buf: ByteBuffer): String {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr.toString(Charsets.UTF_8)
    }

    fun toUtf8(value: String): ByteBuffer {
        // Make sure we don't have invalid UTF-16, check for lone surrogates.
        return Charsets.UTF_8.newEncoder().run {
            onMalformedInput(CodingErrorAction.REPORT)
            encode(CharBuffer.wrap(value))
        }
    }

    override fun lower(value: String): RustBuffer.ByValue {
        val byteBuf = toUtf8(value)
        // Ideally we'd pass these bytes to `ffi_bytebuffer_from_bytes`, but doing so would require us
        // to copy them into a JNA `Memory`. So we might as well directly copy them into a `RustBuffer`.
        val rbuf = RustBuffer.alloc(byteBuf.limit().toULong())
        rbuf.asByteBuffer()!!.put(byteBuf)
        return rbuf
    }

    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per UTF-16 code unit which will always be
    // enough.
    override fun allocationSize(value: String): ULong {
        val sizeForLength = 4UL
        val sizeForString = value.length.toULong() * 3UL
        return sizeForLength + sizeForString
    }

    override fun write(value: String, buf: ByteBuffer) {
        val byteBuf = toUtf8(value)
        buf.putInt(byteBuf.limit())
        buf.put(byteBuf)
    }
}

/**
 * @suppress
 */
public object FfiConverterByteArray: FfiConverterRustBuffer<ByteArray> {
    override fun read(buf: ByteBuffer): ByteArray {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr
    }
    override fun allocationSize(value: ByteArray): ULong {
        return 4UL + value.size.toULong()
    }
    override fun write(value: ByteArray, buf: ByteBuffer) {
        buf.putInt(value.size)
        buf.put(value)
    }
}


// This template implements a class for working with a Rust struct via a handle
// to the live Rust struct on the other side of the FFI.
//
// There's some subtlety here, because we have to be careful not to operate on a Rust
// struct after it has been dropped, and because we must expose a public API for freeing
// theq Kotlin wrapper object in lieu of reliable finalizers. The core requirements are:
//
//   * Each instance holds an opaque handle to the underlying Rust struct.
//     Method calls need to read this handle from the object's state and pass it in to
//     the Rust FFI.
//
//   * When an instance is no longer needed, its handle should be passed to a
//     special destructor function provided by the Rust FFI, which will drop the
//     underlying Rust struct.
//
//   * Given an instance, calling code is expected to call the special
//     `destroy` method in order to free it after use, either by calling it explicitly
//     or by using a higher-level helper like the `use` method. Failing to do so risks
//     leaking the underlying Rust struct.
//
//   * We can't assume that calling code will do the right thing, and must be prepared
//     to handle Kotlin method calls executing concurrently with or even after a call to
//     `destroy`, and to handle multiple (possibly concurrent!) calls to `destroy`.
//
//   * We must never allow Rust code to operate on the underlying Rust struct after
//     the destructor has been called, and must never call the destructor more than once.
//     Doing so may trigger memory unsafety.
//
//   * To mitigate many of the risks of leaking memory and use-after-free unsafety, a `Cleaner`
//     is implemented to call the destructor when the Kotlin object becomes unreachable.
//     This is done in a background thread. This is not a panacea, and client code should be aware that
//      1. the thread may starve if some there are objects that have poorly performing
//     `drop` methods or do significant work in their `drop` methods.
//      2. the thread is shared across the whole library. This can be tuned by using `android_cleaner = true`,
//         or `android = true` in the [`kotlin` section of the `uniffi.toml` file](https://mozilla.github.io/uniffi-rs/kotlin/configuration.html).
//
// If we try to implement this with mutual exclusion on access to the handle, there is the
// possibility of a race between a method call and a concurrent call to `destroy`:
//
//    * Thread A starts a method call, reads the value of the handle, but is interrupted
//      before it can pass the handle over the FFI to Rust.
//    * Thread B calls `destroy` and frees the underlying Rust struct.
//    * Thread A resumes, passing the already-read handle value to Rust and triggering
//      a use-after-free.
//
// One possible solution would be to use a `ReadWriteLock`, with each method call taking
// a read lock (and thus allowed to run concurrently) and the special `destroy` method
// taking a write lock (and thus blocking on live method calls). However, we aim not to
// generate methods with any hidden blocking semantics, and a `destroy` method that might
// block if called incorrectly seems to meet that bar.
//
// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


public interface WaddleClientInterface {

    suspend fun `connect`()

    suspend fun `disconnect`()

    /**
     * XEP-0215 §3.2: fetch the external services (TURN/STUN) the
     * user's own server advertises, as typed entries the app maps to
     * WebRTC ICE servers for LiveKit's RTC configuration at connect
     * time. The query is addressed to the authenticated user's server
     * domain; an empty `<services/>` requests every advertised
     * service type.
     */
    suspend fun `fetchExternalServices`(): List<WaddleExternalService>

    /**
     * Send a `<finish/>` Waddle JMI extension signaling clean
     * teardown after a call ended. Addressed to the peer's full JID
     * so the originating resource sees the finish notice.
     */
    suspend fun `sendCallFinish`(`peerFullJid`: kotlin.String, `sid`: kotlin.String): kotlin.Boolean

    /**
     * Send Waddle's XEP-0353-compatible migration marker:
     * `<finish/>` with `<reason><expired/></reason>` and
     * `<migrated to='new-sid'/>`.
     */
    suspend fun `sendCallFinishMigrated`(`peerFullJid`: kotlin.String, `oldSid`: kotlin.String, `newSid`: kotlin.String): kotlin.Boolean

    /**
     * Send a `<finish/>` carrying an explicit `<reason/>` — the
     * XEP-0353-conformant way for a responder to abandon a session it
     * already answered with `<proceed/>` (a `<reject/>` after proceed
     * is a contradictory double answer; cf. the tie-break-2 example,
     * where an accepted-but-incomplete session finishes with
     * `<expired/>`). Addressed to the peer's full JID.
     */
    suspend fun `sendCallFinishWithReason`(`peerFullJid`: kotlin.String, `sid`: kotlin.String, `reason`: WaddleJingleReason): kotlin.Boolean

    /**
     * Send a XEP-0353 §5.1.2 `<proceed/>` to the *full* JID of the
     * originator (preserved from the propose `from` per §0.6).
     */
    suspend fun `sendCallProceed`(`peerFullJid`: kotlin.String, `sid`: kotlin.String): kotlin.Boolean

    /**
     * Send a XEP-0353 §5.1.1 `<propose/>` to the peer's bare JID.
     * The bare JID lets the responder's server ring every connected
     * resource until one of them proceeds or rejects.
     */
    suspend fun `sendCallPropose`(`peerBareJid`: kotlin.String, `sid`: kotlin.String, `audio`: kotlin.Boolean, `video`: kotlin.Boolean): kotlin.Boolean

    /**
     * Send a XEP-0353 §5.1.3 `<reject/>` to the originator's full JID.
     */
    suspend fun `sendCallReject`(`peerFullJid`: kotlin.String, `sid`: kotlin.String): kotlin.Boolean

    /**
     * Send a XEP-0353 tie-break `<reject/>` carrying
     * `<reason><expired/></reason>` plus `<tie-break/>`.
     */
    suspend fun `sendCallRejectTieBreak`(`peerFullJid`: kotlin.String, `sid`: kotlin.String): kotlin.Boolean

    /**
     * Send a XEP-0353 §5.1.4 `<retract/>` to cancel a ringing call
     * before the peer answers. Addressed to the responder's *bare*
     * JID so every resource that may have been ringing receives the
     * cancellation (XEP-0353 §5.1.4: a retract is addressed to the
     * callee's bare JID, exactly like the originating propose).
     */
    suspend fun `sendCallRetract`(`peerBareJid`: kotlin.String, `sid`: kotlin.String): kotlin.Boolean

    /**
     * Send a XEP-0353 tie-break `<retract/>` carrying
     * `<reason><expired/></reason>` plus `<tie-break/>`.
     */
    suspend fun `sendCallRetractTieBreak`(`peerFullJid`: kotlin.String, `sid`: kotlin.String): kotlin.Boolean

    /**
     * Send a XEP-0353 `<ringing/>` to the caller's *bare* JID so the
     * initiator's server fans the responder's device-ring state out
     * to every caller resource (XEP-0353 §3.2, "Intermediate State:
     * Device Rings"). Emitted when an inbound `<propose/>` lands and
     * the ringing UI starts.
     */
    suspend fun `sendCallRinging`(`peerBareJid`: kotlin.String, `sid`: kotlin.String): kotlin.Boolean

    /**
     * Send a XEP-0166 §7.2 `session-accept` IQ.
     */
    suspend fun `sendCallSessionAccept`(`peerFullJid`: kotlin.String, `responderFullJid`: kotlin.String, `sid`: kotlin.String, `audio`: kotlin.Boolean, `video`: kotlin.Boolean): kotlin.Boolean

    /**
     * Send a XEP-0166 §6.4 `session-initiate` IQ to the peer's full
     * JID. `initiator_full_jid` names the call originator per §7.1.
     */
    suspend fun `sendCallSessionInitiate`(`peerFullJid`: kotlin.String, `initiatorFullJid`: kotlin.String, `sid`: kotlin.String, `audio`: kotlin.Boolean, `video`: kotlin.Boolean): kotlin.Boolean

    /**
     * Send a XEP-0166 §7.4 `session-terminate` IQ.
     */
    suspend fun `sendCallSessionTerminate`(`peerFullJid`: kotlin.String, `sid`: kotlin.String, `reason`: WaddleJingleReason?): kotlin.Boolean

    /**
     * Send a XEP-0166 §7.4 `session-terminate` IQ and report the
     * typed outcome instead of a bare bool. `Orphaned` classifies the
     * Waddle server's `forbidden` + "Jingle terminator is not a
     * participant in this call" stanza error — the call registry
     * entry is already gone, so the caller should still send the
     * XEP-0353 `<finish/>` bookend that keeps both MAM archives
     * consistent (wasm `send_call_session_terminate_with_outcome`
     * parity).
     */
    suspend fun `sendCallSessionTerminateWithOutcome`(`peerFullJid`: kotlin.String, `sid`: kotlin.String, `reason`: WaddleJingleReason?): WaddleCallSessionTerminateOutcome

    /**
     * `urn:waddle:admin:channels:affiliations:0`.
     */
    suspend fun `adminChannelsAffiliations`(`args`: WaddleAdminChannelsAffiliationsArgs): WaddleAdminChannelsAffiliationsPage

    /**
     * `urn:waddle:admin:channels:create:0`.
     */
    suspend fun `adminChannelsCreate`(`args`: WaddleAdminChannelsCreateArgs): WaddleAdminChannelRef

    /**
     * `urn:waddle:admin:channels:delete:0` — destroys the MUC room.
     * Calling this export is the confirmation (see
     * [`Self::admin_spaces_delete`]).
     */
    suspend fun `adminChannelsDelete`(`channelJid`: kotlin.String)

    /**
     * `urn:waddle:admin:channels:kick:0` — operator kick by full
     * occupant JID (server-side XEP-0045 §8.2 role→none).
     */
    suspend fun `adminChannelsKick`(`channelJid`: kotlin.String, `occupantJid`: kotlin.String, `reason`: kotlin.String?): WaddleAdminChannelsKickResult

    /**
     * `urn:waddle:admin:channels:list:0`.
     */
    suspend fun `adminChannelsList`(`args`: WaddleAdminChannelsListArgs): WaddleAdminChannelsListPage

    /**
     * `urn:waddle:admin:channels:occupants:0`.
     */
    suspend fun `adminChannelsOccupants`(`args`: WaddleAdminChannelsOccupantsArgs): WaddleAdminChannelsOccupantsPage

    /**
     * `urn:waddle:admin:channels:set-affiliation:0`.
     */
    suspend fun `adminChannelsSetAffiliation`(`channelJid`: kotlin.String, `memberJid`: kotlin.String, `affiliation`: WaddleMucAffiliation, `reason`: kotlin.String?): WaddleAdminChannelsSetAffiliationResult

    /**
     * `urn:waddle:admin:channels:update:0`.
     */
    suspend fun `adminChannelsUpdate`(`args`: WaddleAdminChannelsUpdateArgs): WaddleAdminChannelRef

    /**
     * `urn:waddle:admin:spaces:create:0`.
     */
    suspend fun `adminSpacesCreate`(`args`: WaddleAdminSpacesCreateArgs): WaddleAdminSpaceRef

    /**
     * `urn:waddle:admin:spaces:delete:0` — cascade-destroys the
     * space and its channels. Calling this export is the
     * confirmation: the server-required `confirm="yes"` literal is
     * supplied here, so UIs MUST show their own confirm dialog
     * first.
     */
    suspend fun `adminSpacesDelete`(`spaceJid`: kotlin.String, `spaceNode`: kotlin.String?)

    /**
     * `urn:waddle:admin:spaces:list:0`.
     */
    suspend fun `adminSpacesList`(`args`: WaddleAdminSpacesListArgs): WaddleAdminSpacesListPage

    /**
     * `urn:waddle:admin:spaces:members:0`.
     */
    suspend fun `adminSpacesMembers`(`args`: WaddleAdminSpacesMembersArgs): WaddleAdminSpacesMembersPage

    /**
     * `urn:waddle:admin:spaces:set-role:0`.
     */
    suspend fun `adminSpacesSetRole`(`spaceJid`: kotlin.String, `spaceNode`: kotlin.String?, `memberJid`: kotlin.String, `role`: WaddleSpaceRole): WaddleAdminSpacesSetRoleResult

    /**
     * `urn:waddle:admin:spaces:update:0`.
     */
    suspend fun `adminSpacesUpdate`(`args`: WaddleAdminSpacesUpdateArgs): WaddleAdminSpaceRef

    /**
     * `urn:waddle:admin:users:list:0`: paginated user directory for
     * the community owner. Non-owners receive a `forbidden` stanza
     * error.
     */
    suspend fun `adminUsersList`(`prefix`: kotlin.String?, `pageSize`: kotlin.UInt?, `afterCursor`: kotlin.String?): WaddleAdminUsersPage

    /**
     * `true` iff the authenticated user is the community owner —
     * i.e. the server accepts a `page_size=1` probe of the V1 users
     * command. Any error (including `forbidden` and transport
     * failures) resolves to `false`: the probe is best-effort
     * gating for the admin UI entry point, never an authorization
     * mechanism — the server re-checks every actual command.
     */
    suspend fun `isCommunityOwner`(): kotlin.Boolean

    suspend fun `discoverTopology`(): WaddleTopology

    suspend fun `discoverUploadService`(): kotlin.String?

    suspend fun `fetchDmHistory`(`peerJid`: kotlin.String, `maxMessages`: kotlin.UInt, `beforeId`: kotlin.String?): WaddleMamPage

    suspend fun `fetchRoomHistory`(`roomJid`: kotlin.String, `maxMessages`: kotlin.UInt, `beforeId`: kotlin.String?): WaddleMamPage

    suspend fun `joinRoom`(`roomJid`: kotlin.String, `nick`: kotlin.String)

    suspend fun `leaveRoom`(`roomJid`: kotlin.String, `nick`: kotlin.String)

    /**
     * Request the XEP-0084 avatar for a user. `known_ids` are item ids
     * whose bytes the caller already caches: when the advertised
     * metadata id is among them the data IQ is skipped (§4.2 "MUST NOT
     * retrieve the image data") and the result carries the id alone.
     * Returns `None` when the target JID hasn't published an avatar or
     * the fetch failed; errors are reported on the event listener so
     * the caller can treat `None` as "fall back to initials".
     */
    suspend fun `requestAvatar`(`jid`: kotlin.String, `knownIds`: List<kotlin.String>): WaddleAvatarResult?

    suspend fun `requestUploadSlot`(`serviceJid`: kotlin.String, `filename`: kotlin.String, `size`: kotlin.ULong, `contentType`: kotlin.String): WaddleUploadSlot?

    /**
     * Full-text search of the account's personal archive, filtered to a
     * 1:1 peer via the standard `with` field. Returns the newest matching
     * page first; an empty page plus an `Error` event on failure,
     * mirroring `fetch_dm_history`.
     */
    suspend fun `searchDmHistory`(`peerJid`: kotlin.String, `query`: kotlin.String, `maxMessages`: kotlin.UInt): WaddleMamPage

    /**
     * Full-text search of a room archive (XEP-0313 extended form field
     * `{urn:xmpp:fulltext:0}fulltext`). Returns the newest matching page
     * first; an empty page plus an `Error` event on failure, mirroring
     * `fetch_room_history`.
     */
    suspend fun `searchRoomHistory`(`roomJid`: kotlin.String, `query`: kotlin.String, `maxMessages`: kotlin.UInt): WaddleMamPage

    suspend fun `sendChatMessage`(`peerJid`: kotlin.String, `body`: kotlin.String, `options`: WaddleSendOptions?): WaddleSendMessageOutcome

    suspend fun `sendGroupchatMessage`(`roomJid`: kotlin.String, `body`: kotlin.String, `options`: WaddleSendOptions?): WaddleSendMessageOutcome

    suspend fun `sendPresence`(`status`: kotlin.String?, `show`: kotlin.String?, `idleSince`: kotlin.String?)

    /**
     * XEP-0490 §3.1 catch-up: retrieve every item from the user's own
     * `urn:xmpp:mds:displayed:0` PEP node. An `item-not-found` reply
     * (no node published yet) is the normal first-run state and
     * returns an empty list rather than an error.
     */
    suspend fun `fetchMdsDisplayed`(): List<WaddleMdsDisplayedEntry>

    /**
     * `urn:waddle:pin:0`: fetch the current pinned-messages list for
     * a MUC room. Empty when the room has no pins. The server gates
     * on room occupancy; a non-occupant caller receives a
     * `forbidden` stanza error.
     */
    suspend fun `fetchRoomPins`(`roomJid`: kotlin.String): List<WaddlePinEntry>

    /**
     * `urn:waddle:link-preview:0`: resolve a composer URL into a
     * send-time preview token scoped to the conversation
     * `scope_jid` (DM peer or room bare JID). URLs that are not
     * HTTPS with a dotted hostname report `Unsupported` without
     * touching the wire (web `firstEligibleHttpsUrl` parity); a
     * malformed or non-matching response reports `Failed`.
     */
    suspend fun `lookupLinkPreview`(`url`: kotlin.String, `scopeJid`: kotlin.String): WaddleLinkPreviewLookup

    /**
     * `urn:waddle:pin:0`: pin a message in a 1:1 DM conversation.
     */
    suspend fun `pinDirectMessage`(`peerJid`: kotlin.String, `targetStanzaId`: kotlin.String): kotlin.Boolean

    /**
     * `urn:waddle:pin:0`: pin the room message identified by the
     * XEP-0359 `by=room` stanza-id. The server gates on Owner/Admin
     * affiliation; a non-admin sender receives a `forbidden` error
     * via the inbound message stream.
     */
    suspend fun `pinMessage`(`roomJid`: kotlin.String, `targetStanzaId`: kotlin.String): kotlin.Boolean

    /**
     * XEP-0490 §3: publish the latest displayed marker for `chat_jid`
     * to the user's own MDS PEP node. `chat_jid` (the PEP item id) is
     * the chat's JID — bare DM contact, bare MUC room, or full MUC
     * occupant for a private message. `stanza_id` is the XEP-0359 id
     * of the displayed message and `stanza_id_by` its resource-less
     * assigning authority. Carries the spec-mandated publish-options
     * as preconditions.
     */
    suspend fun `publishMdsDisplayed`(`chatJid`: kotlin.String, `stanzaId`: kotlin.String, `stanzaIdBy`: kotlin.String): kotlin.Boolean

    /**
     * XEP-0085: send a standalone chat state notification
     * (typing indicator) to a DM peer or room.
     */
    suspend fun `sendChatState`(`peerJid`: kotlin.String, `state`: WaddleChatState, `isMuc`: kotlin.Boolean): kotlin.Boolean

    /**
     * XEP-0308: replace the body of the message identified by
     * `target_id` with `new_body`. Returns the outcome of the fresh
     * send; on success `stanza_id` is the id of the *correction*
     * message (the wasm client's `send_correction` return value).
     */
    suspend fun `sendCorrection`(`peerJid`: kotlin.String, `targetId`: kotlin.String, `newBody`: kotlin.String, `isMuc`: kotlin.Boolean, `options`: WaddleSendOptions?): WaddleSendMessageOutcome

    /**
     * XEP-0333: send a `<displayed id='…'/>` marker acknowledging
     * the message identified by `stanza_id` as read.
     */
    suspend fun `sendDisplayed`(`peerJid`: kotlin.String, `stanzaId`: kotlin.String, `isMuc`: kotlin.Boolean): kotlin.Boolean

    /**
     * XEP-0425: ask the room to moderate (retract) the message
     * identified by `target_stanza_id`. Sent as an IQ to the room;
     * the server gates on moderator privileges and answers
     * `<forbidden/>` otherwise, which surfaces here as `false` plus
     * an `Error` event.
     */
    suspend fun `sendModeration`(`roomJid`: kotlin.String, `targetStanzaId`: kotlin.String, `reason`: kotlin.String?): kotlin.Boolean

    /**
     * XEP-0444: react to the message identified by
     * `target_stanza_id` with the full desired emoji set. Per §3 the
     * stanza carries the *complete* reaction state of this user for
     * that message — send an empty `emojis` to clear all reactions.
     */
    suspend fun `sendReaction`(`targetJid`: kotlin.String, `targetStanzaId`: kotlin.String, `emojis`: List<kotlin.String>, `isMuc`: kotlin.Boolean): kotlin.Boolean

    /**
     * XEP-0424: retract the sender's own message identified by
     * `target_stanza_id`. The stanza carries the §4.2 fallback body
     * marked with a XEP-0428 `<fallback/>` so supporting receivers
     * never render it.
     */
    suspend fun `sendRetraction`(`peerJid`: kotlin.String, `targetStanzaId`: kotlin.String, `isMuc`: kotlin.Boolean): kotlin.Boolean

    /**
     * XEP-0060 explicit subscribe to the user's own MDS node — the
     * fallback path for receiving `+notify` events when this client's
     * presence does not yet carry XEP-0115 caps. The subscriber JID
     * is the bare account JID.
     */
    suspend fun `subscribeMdsDisplayed`(): kotlin.Boolean

    /**
     * XEP-0490 §3 precondition probe: whether the account server
     * advertises `http://jabber.org/protocol/pubsub#publish-options`
     * on disco#info. Publishing MDS markers without it risks a node
     * with wrong access-model defaults; callers should check once per
     * session before the first publish (wasm client parity).
     */
    suspend fun `supportsMdsPublishOptions`(): kotlin.Boolean

    /**
     * `urn:waddle:pin:0`: unpin a message in a 1:1 DM conversation.
     */
    suspend fun `unpinDirectMessage`(`peerJid`: kotlin.String, `targetStanzaId`: kotlin.String): kotlin.Boolean

    /**
     * `urn:waddle:pin:0`: unpin a room message. Same authorization
     * rules as [`Self::pin_message`].
     */
    suspend fun `unpinMessage`(`roomJid`: kotlin.String, `targetStanzaId`: kotlin.String): kotlin.Boolean

    /**
     * XEP-0272 over Waddle's SFU: send the Muji-bearing Jingle
     * `session-initiate` to `calls.<own-domain>`. Resolves on the
     * EMPTY IQ-result ack (XEP-0166 §6.3); the actual
     * `session-accept` with the rewritten LiveKit transport arrives
     * as a separate server-initiated IQ-set through
     * `WaddleClientEvent::Call`, correlated by `sid` (a per-attempt
     * id minted by the caller, so a stale accept from a cancelled
     * same-room retry is ignorable without changing room semantics).
     * `initiator_full_jid` MUST be the bound resource — the server
     * rejects a mismatch with the authenticated session.
     */
    suspend fun `sendMujiSessionInitiate`(`roomJid`: kotlin.String, `initiatorFullJid`: kotlin.String, `sid`: kotlin.String, `video`: kotlin.Boolean)

    /**
     * XEP-0272 leave, mixer half: `session-terminate` with
     * `<reason><success/></reason>` to `calls.<own-domain>`. The
     * server unregisters the participant and revokes every LiveKit
     * token it minted for `(room, identity)`; the call is idempotent.
     * Per XEP-0272 §Leaving, the bare MUC presence
     * ([`Self::update_muji_presence`] with neither flag) MUST go out
     * first.
     */
    suspend fun `sendMujiSessionTerminate`(`roomJid`: kotlin.String, `sid`: kotlin.String)

    /**
     * Publish this occupant's Muji call presence to the room
     * (XEP-0272 §Joining / §Leaving): `preparing=true` for the
     * two-phase setup marker, `active=true` for the content-declaring
     * join (audio implied, video on request), neither for the
     * bare-presence leave marker. `flags` re-stamps the
     * `urn:waddle:in-call:0` raised-hand/mute markers alongside
     * `<muji/>` — meaningless without call participation, so they are
     * dropped on the leave variant.
     */
    suspend fun `updateMujiPresence`(`roomJid`: kotlin.String, `nick`: kotlin.String, `active`: kotlin.Boolean, `preparing`: kotlin.Boolean, `video`: kotlin.Boolean, `flags`: WaddleInCallPresenceFlags)

    /**
     * Fetch the user's Waddle DM-bookmark items (issue #720) from
     * PEP, surfaced with the XEP-0492 fallback mode + rich-payload
     * opt-in (#719) per direct-chat contact. The node is sparse /
     * override-only; an absent node (`item-not-found`) resolves to
     * the empty list.
     */
    suspend fun `fetchDmBookmarks`(): List<WaddleDmBookmarkItem>

    /**
     * Fetch the user's XEP-0402 bookmark items from PEP, surfaced
     * with the XEP-0492 fallback notification mode (when present) per
     * room. Resolves to the empty list when the PEP node is absent
     * (first publish hasn't happened — `item-not-found`).
     *
     * **Deferred** (WASM parity): no XEP-0163 §4.4 `+notify`
     * self-subscription on `urn:xmpp:bookmarks:1` yet, so callers
     * re-fetch on every fresh session-ready; a setting changed on
     * another device reaches this one on the next reconnect.
     */
    suspend fun `fetchUserBookmarks`(): List<WaddleBookmarkItem>

    /**
     * Set the per-DM XEP-0492 notification mode for one direct-chat
     * contact via the Waddle DM-bookmark carrier (issue #720). The
     * node is sparse / override-only: returning the DM to the §3
     * direct-chat default retracts the item (`Removed` outcome)
     * instead of publishing.
     */
    suspend fun `setDmNotificationMode`(`dmJid`: kotlin.String, `mode`: WaddleNotifyMode, `richPayloadOptIn`: kotlin.Boolean): WaddleSetDmNotificationModeOutcome

    /**
     * Set the per-chat XEP-0492 notification mode for one room by
     * merging into the user's XEP-0402 bookmark for that room
     * (creating one with `autojoin=false` when absent, so the call
     * never changes join behavior). Foreign `<advanced/>` children
     * and identity-scoped siblings written by other clients are
     * preserved verbatim (XEP-0492 §3); `rich_payload_opt_in`
     * toggles the Waddle rich XEP-0357 push-summary opt-in (#719).
     */
    suspend fun `setRoomNotificationMode`(`roomJid`: kotlin.String, `mode`: WaddleNotifyMode, `name`: kotlin.String?, `richPayloadOptIn`: kotlin.Boolean): WaddleSetRoomNotificationModeOutcome

    /**
     * XEP-0084 §4.3: publish the empty `<metadata/>` "no avatar"
     * item so subscribers drop their cached avatar.
     */
    suspend fun `disableAvatar`()

    /**
     * Fetch `jid`'s mood/activity/tune PEP nodes in one call (wasm
     * `fetch_user_pep_profile` parity): each node is queried with a
     * XEP-0060 items request, and per-node failures (absent node,
     * stanza error, empty payload) degrade to `None` rather than
     * failing the whole snapshot.
     */
    suspend fun `fetchUserPepProfile`(`jid`: kotlin.String): WaddlePepProfile

    /**
     * XEP-0292: fetch `jid`'s vCard4 from its `urn:xmpp:vcard4` PEP
     * node. `Ok(None)` when the node is absent, empty, or answers
     * with a stanza error (wasm `fetch_vcard4` parity).
     */
    suspend fun `fetchVcard4`(`jid`: kotlin.String): WaddleVCard4?

    /**
     * XEP-0108: publish a user activity. `general` must be one of the
     * 12 registry categories; `specific` (when present) is free-form
     * but must be a wire-safe element name.
     */
    suspend fun `publishActivity`(`general`: kotlin.String, `specific`: kotlin.String?, `text`: kotlin.String?)

    /**
     * XEP-0084 §3: publish `data` as the account's avatar — the
     * base64 data item first, then (after the server ack) the
     * metadata item, both at the SHA-1-of-bytes item id. Pass `0`
     * for `width` / `height` when the dimensions are unknown.
     * `mime_type` must be `image/png` (§5.1 MUST; the client image
     * pipelines always encode PNG) and dimensions must fit
     * `xs:unsignedShort`, else `InvalidArgument`.
     */
    suspend fun `publishAvatar`(`data`: kotlin.ByteArray, `mimeType`: kotlin.String, `width`: kotlin.UInt, `height`: kotlin.UInt)

    /**
     * XEP-0107: publish a user mood. `kind` must be one of the 84
     * registry mood element names (e.g. `happy`).
     */
    suspend fun `publishMood`(`kind`: kotlin.String, `text`: kotlin.String?)

    /**
     * XEP-0118: publish a user tune. At least one field must be set —
     * an all-empty tune is the §3.2 *stop* shape, which is
     * [`Self::retract_tune`]'s job. `rating` is clamped to 1–10 and
     * `length_seconds` to the schema's `xs:unsignedShort` range.
     */
    suspend fun `publishTune`(`tune`: WaddleTune)

    /**
     * XEP-0292: publish the account's own vCard4 at item id
     * `current`. Empty (`None`) properties are omitted on the wire.
     */
    suspend fun `publishVcard4`(`vcard`: WaddleVCard4)

    /**
     * XEP-0108: retract the activity by publishing the empty
     * `<activity/>` payload.
     */
    suspend fun `retractActivity`()

    /**
     * XEP-0107 §2.2: retract the mood by publishing the empty
     * `<mood/>` payload.
     */
    suspend fun `retractMood`()

    /**
     * XEP-0118 §3.2: stop publishing a tune via the empty `<tune/>`
     * payload.
     */
    suspend fun `retractTune`()

    /**
     * XEP-0050 `disable-device` ad-hoc command on `push.<domain>`.
     * Per-device scope — `device_id` is the value returned by the
     * preceding [`register_push_device`] call. Sibling devices on
     * the same node keep receiving fan-out. Returns `true` when the
     * command completes (including the idempotent already-disabled
     * case).
     */
    suspend fun `disablePushDevice`(`pushServiceJid`: kotlin.String, `node`: kotlin.String, `deviceId`: kotlin.String): kotlin.Boolean

    /**
     * XEP-0357 §6.1 `<disable/>` IQ. A `None`/missing `node` disables
     * ALL push nodes at the service for this user.
     */
    suspend fun `disablePushNotifications`(`pushServiceJid`: kotlin.String, `node`: kotlin.String?): kotlin.Boolean

    /**
     * XEP-0357 §5 `<enable/>` IQ against the user's XMPP server.
     * Never carries provider credentials — those flow through
     * `register_push_device` (XEP-0050) at `push.<domain>`.
     */
    suspend fun `enablePushNotifications`(`pushServiceJid`: kotlin.String, `node`: kotlin.String): kotlin.Boolean

    /**
     * XEP-0050 `register-device` ad-hoc command on `push.<domain>`.
     * Drives the multi-step dance and returns the assigned
     * [`WaddleRegisterDeviceResult`] (node id + device id) on
     * success. Returns `None` on failure with the diagnostic on the
     * listener. The caller MUST persist both fields — node feeds
     * the user-server XEP-0357 `<enable/>` IQ, device id scopes the
     * per-device `disable_push_device` opt-out.
     */
    suspend fun `registerPushDevice`(`pushServiceJid`: kotlin.String, `appId`: kotlin.String, `environment`: WaddlePushEnvironment, `credentials`: WaddlePushDeviceCredentials): WaddleRegisterDeviceResult?

    /**
     * XEP-0045 §10.1 room creation: join `localpart@<muc service>`
     * with `nick` (creating the room), then run the §10.1.3/§10.2
     * reserved-room sequence — fetch the config form, merge the
     * initial `patch`, submit — and leave again best-effort (web
     * `createMucRoom` parity: the caller joins properly through the
     * normal flow afterwards). Returns the bare room JID.
     *
     * If `localpart` collides with an existing room the creator does
     * not own, the config fetch fails with a `forbidden` stanza
     * error — surfaced verbatim so the UI can report the conflict.
     */
    suspend fun `createRoom`(`localpart`: kotlin.String, `nick`: kotlin.String, `patch`: WaddleRoomConfigPatch): kotlin.String

    /**
     * XEP-0045 §10.9: destroy the room. Owner-only server-side.
     */
    suspend fun `destroyRoom`(`roomJid`: kotlin.String, `reason`: kotlin.String?)

    /**
     * XEP-0045 §10.2: fetch the owner configuration form and project
     * it into the typed [`WaddleRoomConfig`]. Owner-only; the
     * service answers `forbidden` for everyone else.
     */
    suspend fun `fetchRoomConfig`(`roomJid`: kotlin.String): WaddleRoomConfig

    /**
     * XEP-0045 §8.2 kick: eject the occupant with nickname `nick` by
     * setting `role='none'`. Distinct from a ban — the target's
     * affiliation is untouched and they may rejoin.
     */
    suspend fun `kickOccupant`(`roomJid`: kotlin.String, `nick`: kotlin.String, `reason`: kotlin.String?)

    /**
     * XEP-0045 §9.5: retrieve the affiliation list for one tier.
     * Callers query the four tiers (owner/admin/member/outcast)
     * separately and tolerate per-tier `forbidden` /
     * `service-unavailable` errors — web `MucAdmin.listRoomMembers`
     * parity.
     */
    suspend fun `listRoomMembers`(`roomJid`: kotlin.String, `affiliation`: WaddleMucAffiliation): List<WaddleRoomMemberEntry>

    /**
     * XEP-0055 user search against the account domain's
     * `jabber:iq:search` directory, matching on the `nick` column
     * (wasm `search_users` parity). Backs the members add-member
     * flow.
     */
    suspend fun `searchUsers`(`query`: kotlin.String): List<WaddleUserSearchEntry>

    /**
     * XEP-0045 §5.2 affiliation change addressed by bare JID:
     * promote/demote (member/admin/owner), remove (`none`), or ban
     * (§9.1 `outcast`). The service enforces the admin/owner
     * privilege matrix and answers `forbidden`/`not-allowed`
     * otherwise.
     */
    suspend fun `setRoomAffiliation`(`roomJid`: kotlin.String, `targetJid`: kotlin.String, `affiliation`: WaddleMucAffiliation, `reason`: kotlin.String?)

    /**
     * XEP-0045 §10.2 GET-merge-SET: apply `patch` on top of the
     * service's current form and submit the merged result, so
     * unedited settings round-trip verbatim.
     */
    suspend fun `submitRoomConfig`(`roomJid`: kotlin.String, `patch`: WaddleRoomConfigPatch)

    /**
     * XEP-0449: fetch one sticker pack by id from `owner_jid`'s node
     * (XEP-0060 items-by-id). `node: None` defaults to the PEP
     * `urn:xmpp:stickers:0` node; `Some(node)` targets a generic
     * pubsub node per the `<sticker jid/node>` reference attributes.
     * A missing pack (or empty node) yields `Ok(None)`.
     */
    suspend fun `fetchStickerPack`(`ownerJid`: kotlin.String, `node`: kotlin.String?, `packId`: kotlin.String): WaddleStickerPack?

    /**
     * XEP-0449: fetch every sticker pack published on the
     * `urn:xmpp:stickers:0` PEP node. `owner_jid: None` fetches the
     * account's own packs; `Some(jid)` fetches another user's
     * (readable because the node's access model is `open`). An
     * `item-not-found` reply — no pack ever published — is the normal
     * first-run state and returns an empty list.
     */
    suspend fun `fetchStickerPacks`(`ownerJid`: kotlin.String?): List<WaddleStickerPack>

    /**
     * XEP-0449: publish (create or update/import) a sticker pack on
     * the account's own PEP node. The pubsub item id is recomputed
     * from the pack content per §"Sticker pack hash calculation" —
     * the caller-supplied `pack.id` is ignored — and the id actually
     * published is returned.
     */
    suspend fun `publishStickerPack`(`pack`: WaddleStickerPack): kotlin.String

    /**
     * XEP-0449: retract (delete) one pack from the account's own PEP
     * node. Idempotent: an `item-not-found` reply (the pack is
     * already gone) is success, so a retry after an interrupted
     * retract self-heals. Returns `false` on invalid input, no live
     * session, or any other stanza error (with an `Error` event
     * carrying the diagnostic).
     */
    suspend fun `retractStickerPack`(`packId`: kotlin.String): kotlin.Boolean

    companion object
}

open class WaddleClient: Disposable, AutoCloseable, WaddleClientInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }
    constructor(`config`: WaddleConfig, `listener`: WaddleEventListener) :
        this(UniffiWithHandle,
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_waddle_xmpp_client_ffi_fn_constructor_waddleclient_new(

        FfiConverterTypeWaddleConfig.lower(`config`),FfiConverterTypeWaddleEventListener.lower(`listener`),_status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_waddle_xmpp_client_ffi_fn_free_waddleclient(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_waddle_xmpp_client_ffi_fn_clone_waddleclient(handle, status)
        }
    }


    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `connect`() {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_waddle_xmpp_client_ffi_fn_method_waddleclient_connect(
                uniffiHandle,

            )
        },
        { future, callback, continuation -> UniffiLib.ffi_waddle_xmpp_client_ffi_rust_future_poll_void(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_waddle_xmpp_client_ffi_rust_future_complete_void(future, continuation) },
        { future -> UniffiLib.ffi_waddle_xmpp_client_ffi_rust_future_free_void(future) },
        // lift function
        { Unit },

        // Error FFI converter
        UniffiNullRustCallStatusErrorHandler,
    )
    }


