/**
 * Typed FFI error thrown by the fetch-style methods
 * (`fetch_mds_displayed`, `fetch_room_pins`). Send-style methods keep
 * their `bool` / [`crate::WaddleSendMessageOutcome`] shapes so the
 * existing Swift call sites stay untouched; only new `Result`-returning
 * surfaces use this enum.
 */
sealed class WaddleException: kotlin.Exception() {

    /**
     * No live session — connect first.
     */
    class NotConnected(
        ) : WaddleException() {
        override val message
            get() = ""
    }

    /**
     * A caller-supplied JID failed to parse.
     */
    class InvalidJid(
        ) : WaddleException() {
        override val message
            get() = ""
    }

    /**
     * A caller-supplied argument failed validation before any stanza
     * was built — e.g. an empty XEP-0107 mood kind / XEP-0108 activity
     * general (both become XML element names on the wire), an empty
     * avatar image, an all-empty tune payload, or an XEP-0449 sticker
     * pack whose id, content, or hash algorithm is empty, malformed,
     * or unsupported. Nothing was sent.
     */
    class InvalidArgument(
        ) : WaddleException() {
        override val message
            get() = ""
    }

    /**
     * A caller-supplied Jingle session id was empty or whitespace.
     */
    class InvalidSessionId(
        ) : WaddleException() {
        override val message
            get() = ""
    }

    /**
     * The server answered with an RFC 6120 §8.3 stanza error.
     * `condition` is the defined-condition element name (e.g.
     * `forbidden`); `text` is the optional human-readable `<text/>`.
     */
    class Stanza(

        val `condition`: kotlin.String,

        val `text`: kotlin.String?
        ) : WaddleException() {
        override val message
            get() = "condition=${ `condition` }, text=${ `text` }"
    }

    /**
     * The server answered success but the payload did not match the
     * expected typed shape (server-side bug or schema drift).
     */
    class MalformedResponse(
        ) : WaddleException() {
        override val message
            get() = ""
    }

    /**
     * The websocket transport failed or closed mid-request.
     */
    class Transport(
        ) : WaddleException() {
        override val message
            get() = ""
    }

    /**
     * The request timed out before the server replied.
     */
    class Timeout(
        ) : WaddleException() {
        override val message
            get() = ""
    }

    /**
     * The reply's stamped `from` does not match the queried entity
     * (RFC 6120 §8.1.2.1 defense-in-depth); the payload was
     * discarded rather than trusted.
     */
    class UntrustedReply(
        ) : WaddleException() {
        override val message
            get() = ""
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WaddleException> {
        override fun lift(error_buf: RustBuffer.ByValue): WaddleException = FfiConverterTypeWaddleError.lift(error_buf)
    }


}

